import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    // Number of elements of the sorted array a that are < x (strict) or <= x.
    static int count(long[] a, long x, boolean inclusive) {
        int lo = 0, hi = a.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (a[mid] < x || (inclusive && a[mid] == x)) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    public static void main(String[] args) throws IOException {
        int m = nextInt(), q = nextInt();
        long[] left = new long[m], right = new long[m];
        for (int i = 0; i < m; i++) {
            left[i] = nextLong();
            right[i] = nextLong();
        }
        Arrays.sort(left);
        Arrays.sort(right);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            long x = nextLong();
            // Intervals with left <= x minus those with right < x.
            if (i > 0) sb.append(' ');
            sb.append(count(left, x, true) - count(right, x, false));
        }
        System.out.println(sb);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"sort"
	"strconv"
	"strings"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	m, q := nextInt(), nextInt()
	left := make([]int, m)
	right := make([]int, m)
	for i := 0; i < m; i++ {
		left[i], right[i] = nextInt(), nextInt()
	}
	sort.Ints(left)
	sort.Ints(right)
	out := make([]string, q)
	for i := range out {
		x := nextInt()
		// Intervals with left <= x minus those with right < x.
		covered := sort.SearchInts(left, x+1) - sort.SearchInts(right, x)
		out[i] = strconv.Itoa(covered)
	}
	fmt.Println(strings.Join(out, " "))
}
